INSERT INTO "email_templates" ("key", "module", "role", "label", "send_type", "trigger_text", "recipients", "subject", "body") VALUES
('verifyEmail', 'account', 'account', 'Verify your email', 'auto', 'User signs up', 'Any user', 'Confirm your email address for Smartconferu', '<p>Hi {{first_name}},</p><p>Thanks for signing up. Please confirm this is your email address so we can finish setting up your account.</p><p>Confirm my email: {{verify_link}}</p><p>This link expires in 24 hours. If you didn''t sign up, you can ignore this email.</p><p>The Smartconferu Team</p>'),
('welcome', 'account', 'account', 'Welcome to Smartconferu', 'auto', 'Email verified, or someone new is invited or added (reviewer invitation, co-author)', 'Any user', 'Welcome to Smartconferu, {{first_name}}', '<p>Hi {{first_name}},</p><p>Welcome to Smartconferu! With one account you can submit papers, review for conferences and keep all your certificates and receipts in one place.</p><p>Set up your account and complete your profile (with your ORCID iD) so chairs can match you to the right papers: {{profile_link}}</p><p>The Smartconferu Team</p>'),
('otpCode', 'account', 'account', 'One-time login code', 'auto', 'User logs in with OTP', 'Any user', 'Your Smartconferu login code: {{otp_code}}', '<p>Your one-time login code is:</p><p><b>{{otp_code}}</b></p><p>It''s valid for 10 minutes. Never share this code with anyone. If you didn''t try to log in, you can ignore this email.</p><p>The Smartconferu Team</p>'),
('passwordReset', 'account', 'account', 'Reset your password', 'auto', 'User clicks Forgot password', 'Any user', 'Reset your Smartconferu password', '<p>Hi {{first_name}},</p><p>We got a request to reset your password. Choose a new one here:</p><p>{{reset_link}}</p><p>This link is valid for 1 hour. If you didn''t ask for this, you can ignore this email and your password stays the same.</p><p>The Smartconferu Team</p>'),
('passwordChanged', 'account', 'account', 'Password changed', 'auto', 'Password changed', 'Any user', 'Your Smartconferu password was changed', '<p>Hi {{first_name}},</p><p>The password on your account was changed on {{changed_at}}.</p><p>If this was you, there''s nothing else to do. If it wasn''t, reset your password straight away and contact support@smartconferu.com.</p><p>The Smartconferu Team</p>'),
('emailChangeConfirm', 'account', 'account', 'Confirm new email address', 'auto', 'User changes login email', 'Any user (new address); Old address gets a notice', 'Confirm your new login email', '<p>Hi {{first_name}},</p><p>You asked to use this address to log in to Smartconferu. Please confirm it:</p><p>{{verify_link}}</p><p>Until you confirm, your old address keeps working. We''ve also let your old address know about this change.</p><p>The Smartconferu Team</p>'),
('coAuthorAdded', 'account', 'author', 'You were added as a co-author', 'auto', 'Author submits a paper listing other people as authors', 'Co-author', '{{submitter_name}} added you as a co-author — {{conference_acronym}}', '<p>Dear {{first_name}},</p><p>{{submitter_name}} has listed you as a co-author of "{{paper_title}}", submitted to {{conference_name}}.</p><p>{{updates_note}}</p><p>Log in, or claim your free account with this email address, to follow the paper: {{claim_link}}</p><p>If you''re not an author of this paper, please reply to let us know.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('orgInvite', 'team', 'roles', 'Invitation to join organization', 'auto', 'Org Admin invites an admin', 'Org Admin', '{{inviter_name}} invited you to manage {{org_name}} on Smartconferu', '<p>Hi {{first_name}},</p><p>{{inviter_name}} has invited you to become an admin of {{org_name}} on Smartconferu. Org admins can create conferences and manage the organization''s team.</p><p>Accept the invitation: {{accept_link}}</p><p>The Smartconferu Team</p>'),
('teamInvite', 'team', 'roles', 'Invitation to conference team', 'chair', 'Chair adds Program Chair / Track Chair / Finance / Registration team', 'Team member', 'You''re invited to join the {{conference_acronym}} team as {{role}}', '<p>Dear {{first_name}},</p><p>You''ve been invited to join the organizing team of {{conference_name}} as <b>{{role}}</b>.</p><p>Tracks: {{tracks}}</p><p>Once you accept you''ll be able to open the conference workspace with the access that comes with this role.</p><p>Accept the invitation: {{accept_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('teamInviteReminder', 'team', 'roles', 'Team invitation reminder', 'scheduled', 'Invitation not accepted after 3 days', 'Team member', 'Reminder: your invitation to the {{conference_acronym}} team', '<p>Dear {{first_name}},</p><p>Just a reminder that your invitation to the {{conference_name}} team is still waiting.</p><p>Accept it here: {{accept_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('teamMemberJoined', 'team', 'chair', 'Team member joined', 'auto', 'Team member accepts', 'Conference Chair', '{{member_name}} joined the {{conference_acronym}} team', '<p>Hi {{first_name}},</p><p>{{member_name}} accepted your invitation and joined the {{conference_name}} team as {{role}} today.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('teamRoleChanged', 'team', 'roles', 'Your role was changed', 'auto', 'Chair changes role or tracks', 'Team member', 'Your role on {{conference_acronym}} has changed', '<p>Dear {{first_name}},</p><p>Your role on the {{conference_name}} team has changed.</p><p>Before: {{old_role}}<br>Now: <b>{{new_role}}</b></p><p>Your access in the conference workspace has been updated to match.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('teamAccessRemoved', 'team', 'roles', 'Your access was removed', 'auto', 'Chair removes team member', 'Team member', 'Your access to {{conference_acronym}} has ended', '<p>Dear {{first_name}},</p><p>Your access to the {{conference_name}} workspace ended today. Thank you for your help with the conference.</p><p>If you think this is a mistake, please contact the Conference Chair.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('conferenceCreated', 'setup', 'chair', 'Conference created', 'auto', 'Chair creates a conference (draft)', 'Conference Chair', '{{conference_name}} is created — here''s what''s next', '<p>Hi {{first_name}},</p><p>{{conference_name}} is saved as a draft. Before you publish, work through the setup checklist: dates, tracks, submission form, review form and registration fees.</p><p>Open your conference: {{dashboard_link}}</p><p>The Smartconferu Team</p>'),
('deletionApproved', 'setup', 'chair', 'Conference deleted', 'auto', 'Super Admin approves a deletion request', 'Conference Chair (who asked)', '{{conference_name}} was deleted', '<p>Dear {{first_name}},</p><p>As you asked, {{conference_name}} was deleted. It no longer appears in any list for you, its authors or its reviewers.</p><p>If this was a mistake, reply to this email and we can bring it back.</p><p>The Smartconferu Team</p>'),
('deletionRejected', 'setup', 'chair', 'Deletion not approved', 'auto', 'Super Admin rejects a deletion request', 'Conference Chair (who asked)', '{{conference_name}} was not deleted', '<p>Dear {{first_name}},</p><p>We didn''t delete {{conference_name}}. It stays archived.</p><p>Reason: {{admin_note}}</p><p>You can send a new request from Conference Settings, or restore the conference there if you want it open again.</p><p>The Smartconferu Team</p>'),
('conferenceRestored', 'setup', 'chair', 'Deleted conference brought back', 'auto', 'Super Admin brings a deleted conference back', 'Conference Chair (who asked)', '{{conference_name}} is back', '<p>Dear {{first_name}},</p><p>{{conference_name}} has been brought back, with all its papers, reviews and authors. It is archived, so it takes no new submissions yet.</p><p>When you''re ready, open Conference Settings and press Restore conference: {{dashboard_link}}</p><p>The Smartconferu Team</p>'),
('setupReminder', 'setup', 'chair', 'Setup not finished', 'scheduled', 'Draft conference and planned submission opening is in 7 days', 'Conference Chair', '{{conference_acronym}} opens on {{open_date}} — setup isn''t finished', '<p>Hi {{first_name}},</p><p>Submissions for {{conference_name}} are planned to open on {{open_date}}, but a few things are still missing:</p><p>{{missing_items}}</p><p>Finish these and publish the conference so authors can submit on time.</p><p>The Smartconferu Team</p>'),
('cfpLive', 'setup', 'chair', 'Call for Papers is live', 'auto', 'Chair publishes the conference', 'Conference Chair; All team members', 'The {{conference_acronym}} Call for Papers is live', '<p>Hi {{first_name}},</p><p>The Call for Papers for {{conference_name}} is now public.</p><p>Public page: {{cfp_link}}<br>Submission link: {{submission_link}}</p><p>Share these with your network, mailing lists and partners.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('submissionsOpen', 'setup', 'chair', 'Submissions open today', 'auto', 'Scheduled opening date reached', 'Conference Chair; Track Chairs', 'Submissions for {{conference_acronym}} are open', '<p>Hi {{first_name}},</p><p>The submission form for {{conference_name}} opened today and is accepting papers.</p><p>Submission link: {{submission_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('submissionReceived', 'submission', 'author', 'Submission received', 'auto', 'Author clicks Submit', 'Author (submitting); All co-authors', 'Submission received: {{paper_title}} ({{submission_id}})', '<p>Dear {{first_name}},</p><p>Thank you — your paper has been submitted to {{conference_name}}.</p><p>Submission ID: <b>{{submission_id}}</b><br>Title: {{paper_title}}<br>Track: {{track}}<br>Type: {{presentation_type}}</p><p>You can edit your submission until {{edit_deadline}}. We''ll email you again when the decision is ready.</p><p>View your submission: {{submission_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('newSubmissionAlert', 'submission', 'chair', 'New submission alert', 'auto', 'Paper submitted', 'Conference Chair; Track Chair of that track', 'New submission {{submission_id}} in {{track}}', '<p>Hi {{first_name}},</p><p>A new paper was submitted to {{conference_name}}.</p><p>{{submission_id}} · {{paper_title}}<br>Track: {{track}}<br>Submitted by: {{submitter_name}}</p><p>Open the paper: {{submission_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('submissionEdited', 'submission', 'author', 'Submission edited', 'auto', 'Author edits before deadline', 'Author (submitting); All co-authors', 'Your submission {{submission_id}} was updated', '<p>Dear {{first_name}},</p><p>"{{paper_title}}" ({{submission_id}}) was updated today.</p><p>What changed: {{changed_fields}}</p><p>If you didn''t make this change, please contact the organisers.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('submissionWithdrawn', 'submission', 'author', 'Submission withdrawn', 'auto', 'Author withdraws', 'Author (submitting); Co-authors, Chair, Track Chair', 'Withdrawn: {{paper_title}} ({{submission_id}})', '<p>Dear {{first_name}},</p><p>"{{paper_title}}" ({{submission_id}}) has been withdrawn from {{conference_name}}. It will not be considered for the programme.</p><p>If this was a mistake, contact the organisers as soon as possible.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('submittedOnBehalf', 'submission', 'author', 'Submitted on your behalf', 'auto', 'Chair submits for an author', 'Author (submitting); Co-authors', '{{chair_name}} submitted "{{paper_title}}" for you', '<p>Dear {{first_name}},</p><p>{{chair_name}} submitted "{{paper_title}}" ({{submission_id}}) to {{conference_name}} on your behalf.</p><p>Please check the details are correct: {{submission_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('draftReminder', 'submission', 'author', 'Your paper is not submitted yet', 'scheduled', 'Paper upload pending, deadline in 7 days and 1 day', 'Author (submitting)', 'Your paper is not submitted yet — {{conference_acronym}}', '<p>Dear {{first_name}},</p><p>"{{paper_title}}" has <b>not been submitted</b> yet — the paper is still to be uploaded.</p><p>Still missing: {{missing_items}}</p><p>The deadline is {{deadline}}. Finish and submit here: {{submission_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('deadlineApproaching', 'submission', 'author', 'Submission deadline approaching', 'scheduled', 'Deadline in 7 days (optional 1 day)', 'Author (submitting)', '{{conference_acronym}} submissions close {{deadline_local}}', '<p>Dear {{first_name}},</p><p>A reminder that submissions to {{conference_name}} close on <b>{{deadline_local}}</b> (your time zone).</p><p>Submit here: {{submission_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('deadlineExtended', 'submission', 'author', 'Deadline extended', 'chair', 'Chair changes the deadline', 'Author (submitting); Co-authors', '{{conference_acronym}} submission deadline extended', '<p>Dear {{first_name}},</p><p>Good news — the submission deadline for {{conference_name}} has been extended.</p><p>New deadline: <b>{{new_deadline_local}}</b> (your time zone)</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('fixSubmission', 'submission', 'author', 'Please fix your submission', 'chair', 'Chair flags a fixable problem', 'Author (submitting)', 'Action needed: please fix your submission {{submission_id}}', '<p>Dear {{first_name}},</p><p>We found a problem with "{{paper_title}}" that needs fixing before it can move forward:</p><p>{{issue_text}}</p><p>Please update your submission by <b>{{fix_by}}</b>: {{submission_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('deskRejection', 'submission', 'author', 'Desk rejection', 'chair', 'Chair rejects without review', 'Author (submitting); Co-authors', 'Update on "{{paper_title}}" — {{conference_acronym}}', '<p>Dear {{first_name}},</p><p>Thank you for choosing {{conference_name}} to share "{{paper_title}}". We truly appreciate the effort behind your work.</p><p>After careful review, we won''t be able to include it in this year''s programme. The main point behind this decision:</p><p>{{reason}}</p><p>This reflects the fit with this edition''s requirements, not the value of your research. We''d encourage you to keep building on it, and we''d be delighted to see a future submission from you.</p><p>Thank you again, and we wish you all the best with your research.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('submissionsClosedSummary', 'submission', 'chair', 'Submissions closed: summary', 'auto', 'Deadline passes', 'Conference Chair; Track Chairs', '{{conference_acronym}} submissions closed: {{total_submissions}} papers', '<p>Hi {{first_name}},</p><p>Submissions for {{conference_name}} are now closed.</p><p>Total submitted: <b>{{total_submissions}}</b><br>By track: {{by_track}}</p><p>Drafts that were never submitted are listed on your dashboard.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('similarityFlag', 'submission', 'chair', 'Possible duplicate or similarity flag', 'auto', 'System flags a paper', 'Conference Chair; Track Chair', 'Similarity flag on {{submission_ids}}', '<p>Hi {{first_name}},</p><p>The system flagged {{submission_ids}} for a closer look.</p><p>Why: {{flag_reason}}</p><p>Open the Plagiarism page to compare and decide what to do.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('screeningCorrection', 'submission', 'author', 'Correction needed (initial check)', 'chair', 'Chair requests a correction after the initial check', 'Author (corresponding); Co-authors', 'Next step for your paper – {{submission_id}}', '<p>Dear {{first_name}},</p><p>Thank you for submitting your paper to {{conference_name}}. We appreciate the effort behind it, and we''d love to see it in the programme.</p><p>Paper ID: {{submission_id}}<br>Title: {{paper_title}}</p><p>To move it forward, there are a few things to take care of:</p><p>{{correction_reasons}}</p><p>You''re very close. Once you upload the updated version by <b>{{correction_deadline}}</b> from your submission page, we''ll take it from there: {{upload_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('screeningRevision', 'submission', 'author', 'Revision required (plagiarism check)', 'chair', 'Chair requests a revision after the iThenticate report', 'Author (corresponding); Co-authors', 'Next step for your paper – {{submission_id}}', '<p>Dear {{first_name}},</p><p>Thank you for submitting your paper to {{conference_name}}. We appreciate the effort behind it, and we''d love to see it in the programme.</p><p>Paper ID: {{submission_id}}<br>Title: {{paper_title}}</p><p>To move it forward, there are a few things to take care of:</p><p>{{revision_reasons}}</p><p>You''re very close. Once you upload the updated version by <b>{{revision_deadline}}</b> from your submission page, we''ll take it from there: {{upload_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('screeningCorrectionReminder', 'submission', 'author', 'Reminder: correction needed (initial check)', 'chair', 'Chair sends a reminder after the correction request', 'Author (corresponding); Co-authors (only if the Chair ticks it)', 'Reminder: Next step for your paper – {{submission_id}}', '<p>Dear {{first_name}},</p><p>Paper ID: {{submission_id}}<br>Title: {{paper_title}}</p><p>Just a friendly nudge: your paper is nearly ready to move forward, and a few small things are left:</p><p>{{correction_reasons}}</p><p>We''re keen to see your updated version. The due date is <b>{{correction_deadline}}</b>, and you can upload it here: {{upload_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('screeningCorrectionLastChance', 'submission', 'author', 'Last chance: correction needed (initial check)', 'chair', 'Chair sends a final notice after the correction request', 'Author (corresponding); Co-authors (only if the Chair ticks it)', 'Final reminder: Next step for your paper – {{submission_id}}', '<p>Dear {{first_name}},</p><p>Paper ID: {{submission_id}}<br>Title: {{paper_title}}</p><p>This is a final reminder, and we really hope to keep your paper with us. These points are still open:</p><p>{{correction_reasons}}</p><p>If you can upload the updated version by <b>{{correction_deadline}}</b>, your paper can continue on its way: {{upload_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('screeningRevisionReminder', 'submission', 'author', 'Reminder: revision required (plagiarism check)', 'chair', 'Chair sends a reminder after the revision request', 'Author (corresponding); Co-authors (only if the Chair ticks it)', 'Reminder: Next step for your paper – {{submission_id}}', '<p>Dear {{first_name}},</p><p>Paper ID: {{submission_id}}<br>Title: {{paper_title}}</p><p>Just a friendly nudge: your paper is nearly ready to move forward, and a few small things are left:</p><p>{{revision_reasons}}</p><p>We''re keen to see your updated version. The due date is <b>{{revision_deadline}}</b>, and you can upload it here: {{upload_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('screeningRevisionLastChance', 'submission', 'author', 'Last chance: revision required (plagiarism check)', 'chair', 'Chair sends a final notice after the revision request', 'Author (corresponding); Co-authors (only if the Chair ticks it)', 'Final reminder: Next step for your paper – {{submission_id}}', '<p>Dear {{first_name}},</p><p>Paper ID: {{submission_id}}<br>Title: {{paper_title}}</p><p>This is a final reminder, and we really hope to keep your paper with us. These points are still open:</p><p>{{revision_reasons}}</p><p>If you can upload the updated version by <b>{{revision_deadline}}</b>, your paper can continue on its way: {{upload_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('screeningCoAuthor', 'submission', 'author', 'Copy for co-authors (screening)', 'chair', 'Chair ticks “Also email co-authors” on any screening email', 'Co-author (each by name)', '{{kind_note}}Update on your co-authored paper – {{submission_id}}', '<p>Dear {{first_name}},</p><p>Your co-authored paper "{{paper_title}}" ({{submission_id}}) is moving ahead and needs a few updates first. {{corresponding_name}}, the corresponding author, has been asked to upload the updated version by <b>{{deadline}}</b>.</p><p>Nothing is needed from you, but a quick word with {{corresponding_name}} would help.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('screeningPassed', 'submission', 'author', 'Plagiarism check passed (optional)', 'chair', 'Chair marks a paper plagiarism clear and ticks “Let the author know”', 'Author (corresponding)', 'Plagiarism check passed – {{submission_id}}', '<p>Dear {{first_name}},</p><p>Good news: your paper "{{paper_title}}" ({{submission_id}}) passed the plagiarism check and now moves on to peer review. We''ll be in touch once there''s a decision.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('reviewerInvited', 'recruitment', 'reviewer', 'You''ve been added as a reviewer', 'auto', 'Chair adds or imports a reviewer', 'Reviewer', 'You''ve been added as a reviewer for {{conference_acronym}}', '<p>Dear {{first_name}},</p><p>You''ve been added to the review committee of {{conference_name}}.</p><p>Tracks: {{tracks}}<br>Review period: {{review_period}}</p><p>New to Smartconferu? Activate your account and set a password: {{activate_link}}<br>Already have an account? Just log in: {{login_link}}</p><p>Reviewer guidelines are available once you log in.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('reviewerActivateReminder', 'recruitment', 'reviewer', 'Activate your reviewer account', 'scheduled', 'Account not activated 3 and 7 days after being added', 'Reviewer', 'Reminder: activate your {{conference_acronym}} reviewer account', '<p>Dear {{first_name}},</p><p>Your reviewer account for {{conference_name}} isn''t active yet. It only takes a minute:</p><p>{{activate_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('reviewersInactiveChair', 'recruitment', 'chair', 'Reviewers not yet active', 'scheduled', 'Daily while any added reviewer has not activated', 'Conference Chair', '{{conference_acronym}}: reviewers who haven''t activated yet', '<p>Hi {{first_name}},</p><p>These reviewers haven''t activated their account yet:</p><p>{{inactive_list}}</p><p>You can resend their invitation from Peer Review › Reviewers.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('reviewerProfileReminder', 'recruitment', 'reviewer', 'Complete your reviewer profile', 'scheduled', 'Profile missing expertise or institution, 5 days after joining', 'Reviewer', 'Help us match you to the right papers', '<p>Dear {{first_name}},</p><p>Your reviewer profile is missing: {{missing_fields}}.</p><p>The chair uses these to match you with papers in your area, so a complete profile means more relevant assignments.</p><p>Update your profile: {{profile_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('reviewAssignment', 'reviewing', 'reviewer', 'Papers assigned to you', 'auto', 'Chair confirms assignment (one email per batch)', 'Reviewer', '{{conference_acronym}}: papers assigned to you for review', '<p>Dear {{first_name}},</p><p>The following papers have been assigned to you:</p><p>{{paper_list}}</p><p>Please submit your reviews by <b>{{review_deadline}}</b>.</p><p>Start reviewing: {{review_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('assignmentRemoved', 'reviewing', 'reviewer', 'Assignment removed', 'auto', 'Chair removes a reviewer from a paper before the deadline', 'Reviewer', 'Update: "{{paper_title}}" removed from your queue', '<p>Dear {{first_name}},</p><p>"{{paper_title}}" no longer needs your review and has been removed from your queue. Nothing else changes for your other papers.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('reviewDueSoon', 'reviewing', 'reviewer', 'Review reminder 1 — days left', 'scheduled', 'A set number of days before a reviewer''s deadline (Peer Review › Review timeline)', 'Reviewer', '{{days_left}} left to review — {{conference_acronym}}', '<p>Dear {{first_name}},</p><p>A friendly reminder: you have <b>{{days_left}}</b> left to submit your review (due <b>{{review_deadline}}</b>). Still pending:</p><p>{{pending_list}}</p><p>Open your review queue: {{review_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('reviewLastDay', 'reviewing', 'reviewer', 'Review reminder 2 — last day', 'scheduled', 'The last day of a reviewer''s deadline (Peer Review › Review timeline)', 'Reviewer', 'Last day to review — {{conference_acronym}}', '<p>Dear {{first_name}},</p><p>Today is the last day to submit your review (due <b>{{review_deadline}}</b>). These are still pending:</p><p>{{pending_list}}</p><p>Please submit them today: {{review_link}}</p><p>If you can''t finish in time, let the chair know as soon as you can so the paper can be reassigned.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('reviewOverdue', 'reviewing', 'reviewer', 'Review overdue', 'scheduled', 'Deadline passed: first day and last day of the grace period', 'Reviewer; Track Chair on the last one', 'Overdue: your {{conference_acronym}} review', '<p>Dear {{first_name}},</p><p>The review deadline has passed and these reviews are still missing:</p><p>{{overdue_list}}</p><p>The form stays open until <b>{{grace_end}}</b>. After that, the chair may reassign the paper.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('reviewerPersonalReminder', 'reviewing', 'reviewer', 'Personal reminder from the chair', 'chair', 'Chair clicks Send reminder on one reviewer', 'Reviewer', 'A note from {{chair_name}} about "{{paper_title}}"', '<p>Dear {{first_name}},</p><p>{{message}}</p><p>Paper: {{paper_title}}<br>Please submit your review by {{grace_end}}.</p><p>Thank you,<br>{{chair_name}}</p>'),
('overdueDigestChair', 'reviewing', 'chair', 'Overdue reviews: daily list', 'scheduled', 'Every day during the grace period', 'Conference Chair; Track Chair (own track)', '{{conference_acronym}}: overdue reviews today', '<p>Hi {{first_name}},</p><p>These reviews are overdue. The grace period ends {{grace_end}}.</p><p>{{overdue_list}}</p><p>Use "Send reminder" next to a reviewer to send a personal nudge.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('reviewFormLocked', 'reviewing', 'reviewer', 'Grace period over: review form locked', 'auto', 'Grace period ends without a review', 'Reviewer', 'Review form locked: "{{paper_title}}"', '<p>Dear {{first_name}},</p><p>The grace period for "{{paper_title}}" has ended and the review form is now locked. The chair will decide whether to extend your deadline or reassign the paper.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('missedReviewsChair', 'reviewing', 'chair', 'Papers need action: missed reviews', 'auto', 'Grace period ends with reviews missing', 'Conference Chair; Track Chair (own track)', '{{conference_acronym}}: papers with missed reviews', '<p>Hi {{first_name}},</p><p>The grace period is over and these papers are missing reviews:</p><p>{{paper_list}}<br>Missing: {{missing_reviewers}}</p><p>For each one you can extend, replace the reviewer, decide with the reviews received, or review it yourself.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('reviewDeadlineExtended', 'reviewing', 'reviewer', 'Review deadline extended for you', 'chair', 'Chair extends for one reviewer (also after grace) or all', 'Reviewer', 'Your review deadline is extended to {{new_deadline}}', '<p>Dear {{first_name}},</p><p>Your review deadline for {{conference_name}} has been extended to <b>{{new_deadline}}</b> and the form is open again.</p><p>Continue your review: {{review_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('assignmentCancelled', 'reviewing', 'reviewer', 'Review assignment cancelled', 'auto', 'Chair replaces the reviewer or cancels the missing review', 'Reviewer', '"{{paper_title}}" no longer needs your review', '<p>Dear {{first_name}},</p><p>"{{paper_title}}" no longer needs your review — the assignment has been closed. Thank you for your time on {{conference_name}}.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('reviewThanks', 'reviewing', 'reviewer', 'Thank you for your review', 'auto', 'Reviewer submits a review', 'Reviewer', 'Thank you for your review of "{{paper_title}}"', '<p>Dear {{first_name}},</p><p>Thank you for reviewing "{{paper_title}}". A copy of your review is below for your records:</p><p>{{review_copy}}</p><p>You can edit it until the decision is made.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('reviewEditedByChair', 'reviewing', 'reviewer', 'Review edited by the chair', 'auto', 'Chair edits a submitted review', 'Reviewer', 'The chair edited your review of "{{paper_title}}"', '<p>Dear {{first_name}},</p><p>The conference chair made changes to the review you submitted for "{{paper_title}}". You can see the updated version on your review page.</p><p>{{submission_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('reviewSubmittedChair', 'reviewing', 'chair', 'Review submitted', 'auto', 'Reviewer submits', 'Conference Chair; Track Chair', 'New review on "{{paper_title}}" — score {{score}}', '<p>Hi {{first_name}},</p><p>{{reviewer_name}} submitted a review of "{{paper_title}}".</p><p>Score: <b>{{score}}</b></p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('chairDecisionReady', 'reviewing', 'chair', 'Paper ready for decision', 'auto', 'Last required review arrives', 'Conference Chair; Track Chair', 'Ready for decision: "{{paper_title}}"', '<p>Hi {{first_name}},</p><p>All required reviews are in for "{{paper_title}}".</p><p>Average score: <b>{{avg_score}}</b><br>Spread: {{score_spread}}</p><p>Record a decision: {{submission_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('reviewProgressDigest', 'reviewing', 'chair', 'Review progress digest', 'scheduled', 'Daily or weekly during review period', 'Conference Chair; Track Chairs (own track)', '{{conference_acronym}} review progress: {{done}} done, {{pending}} pending', '<p>Hi {{first_name}},</p><p>Review progress for {{conference_name}}:</p><p>Done: <b>{{done}}</b> · Pending: {{pending}} · Overdue: {{overdue}}</p><p>Papers at risk and reviewers with the most pending reviews are on your Peer Review page.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('chairMessageReviewer', 'reviewing', 'reviewer', 'Message from the chair about a paper', 'chair', 'Chair asks reviewer for clarification or discussion', 'Reviewer', 'Question from the chair about "{{paper_title}}"', '<p>Dear {{first_name}},</p><p>The chair has a question about your review of "{{paper_title}}":</p><p>{{message}}</p><p>Reply in the paper''s discussion: {{review_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('reviewerBroadcast', 'reviewing', 'reviewer', 'Message to all reviewers', 'bulk', 'Chair sends a general message', 'Reviewer', 'A message for {{conference_acronym}} reviewers', '<p>Dear {{first_name}},</p><p>{{message}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('acceptance', 'decision', 'author', 'Paper accepted', 'chair', 'Chair releases an Accept decision', 'Author (submitting); Co-authors', 'Accepted: "{{paper_title}}" — {{conference_acronym}}', '<p>Dear {{first_name}},</p><p>Congratulations! "{{paper_title}}" has been accepted for {{conference_name}} as a <b>{{presentation_type}}</b> presentation.</p><p>{{chair_note}}Reviewer comments:<br>{{reviews_for_author}}</p><p>Next steps:<br>1. Register by {{registration_deadline}}<br>2. Upload your camera-ready version by {{camera_ready_deadline}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('minorRevision', 'decision', 'author', 'Minor revision required', 'chair', 'Chair releases a Minor revision decision', 'Author (submitting); Co-authors', 'Minor revision requested: "{{paper_title}}"', '<p>Dear {{first_name}},</p><p>Thank you for your strong work. "{{paper_title}}" is close to acceptance, and a few small changes will get it there.</p><p>{{chair_note}}Reviewer comments:<br>{{reviews_for_author}}</p><p>We''d be glad to see your revised paper. Please upload it by <b>{{revision_deadline}}</b>: {{upload_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('majorRevision', 'decision', 'author', 'Major revision required', 'chair', 'Chair releases a Major revision decision', 'Author (submitting); Co-authors', 'Major revision requested: "{{paper_title}}"', '<p>Dear {{first_name}},</p><p>Thank you for submitting "{{paper_title}}". The reviewers have shared detailed feedback, and with some substantial changes the paper can be a strong fit before a final decision is made.</p><p>{{chair_note}}Reviewer comments:<br>{{reviews_for_author}}</p><p>We''d be glad to see your revised version. Please upload it by <b>{{revision_deadline}}</b>: {{upload_link}}</p><p>The revised version will go back to the reviewers.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('rejection', 'decision', 'author', 'Paper not accepted', 'chair', 'Chair releases a Reject decision', 'Author (submitting); Co-authors', 'Update on "{{paper_title}}" — {{conference_acronym}}', '<p>Dear {{first_name}},</p><p>Thank you for submitting "{{paper_title}}" to {{conference_name}}, and for the effort behind it. Choosing from the submissions is never easy, and after careful consideration we won''t be able to include this paper in this year''s programme.</p><p>This is not a reflection of the value of your research. The reviewers took the time to share their thoughts, and we hope they help you take the work further:</p><p>{{chair_note}}Reviewer comments:<br>{{reviews_for_author}}</p><p>We''d be delighted to see you at a future edition, and we wish you every success with this work.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('waitlisted', 'decision', 'author', 'Paper waitlisted', 'chair', 'Chair releases a Waitlist decision', 'Author (submitting); Co-authors', '"{{paper_title}}" is on the {{conference_acronym}} waitlist', '<p>Dear {{first_name}},</p><p>Thank you for your work on "{{paper_title}}", and for your patience. The paper has been placed on the waitlist, which means it is still very much in consideration and may be accepted if a slot in the programme opens up.</p><p>You''ll hear our final decision by <b>{{final_decision_date}}</b>.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('decisionChanged', 'decision', 'author', 'Decision changed', 'chair', 'Chair overrides a released decision', 'Author (submitting); Co-authors', 'Updated decision on "{{paper_title}}"', '<p>Dear {{first_name}},</p><p>The decision on "{{paper_title}}" has been updated.</p><p>New decision: <b>{{new_decision}}</b><br>Reason: {{reason}}</p><p>This replaces our earlier email. Details are in your dashboard.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('finalDecisionReviewers', 'decision', 'reviewer', 'Final decision (for reviewers)', 'auto', 'Decision released', 'Reviewer', 'Final decision on "{{paper_title}}"', '<p>Dear {{first_name}},</p><p>The final decision on "{{paper_title}}", which you reviewed, is: <b>{{decision}}</b>.</p><p>Thank you for helping shape the {{conference_name}} programme.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('registrationConfirmed', 'after', 'registration', 'Registration confirmed', 'auto', 'Attendee completes registration', 'Registrant', 'Your registration for {{conference_name}} has been confirmed', '<p>Dear {{first_name}},</p><p>Your registration for {{conference_name}} ({{registration_type}}) is confirmed. A receipt has been sent separately.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('registrationDeclined', 'after', 'registration', 'Offline payment declined', 'chair', 'Registration team declines an offline payment', 'Registrant', 'Offline payment declined for {{conference_name}}', '<p>Dear {{first_name}},</p><p>Your offline payment for {{conference_name}} could not be verified and has been declined. Please contact us for assistance.</p><p>Best regards,<br>The {{conference_name}} Team</p>'),
('cameraReadyReminder', 'after', 'author', 'Camera-ready reminder', 'scheduled', 'Ahead of the camera-ready deadline', 'Author (submitting)', 'Camera-ready copy due for "{{paper_title}}"', '<p>Dear {{first_name}},</p><p>The camera-ready version of "{{paper_title}}" is due by <b>{{camera_ready_deadline}}</b>.</p><p>Upload your final files: {{submission_link}}</p><p>Best regards,<br>The {{conference_name}} Team</p>')
